pub fn numpy_insert<T>(mut arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Vec::insert already shifts all elements at and after `idx` to the right,
    // and places `value` at position `idx`.
    arr.insert(idx, value);
    arr
}

